import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const g=JSON.parse('{"title":"Combat foundations","description":"","frontmatter":{},"headers":[],"relativePath":"game-design/combat/overview.md","filePath":"game-design/combat/overview.md"}'),o={name:"game-design/combat/overview.md"};function r(s,e,l,d,m,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="combat-foundations" tabindex="-1">Combat foundations <a class="header-anchor" href="#combat-foundations" aria-label="Permalink to &quot;Combat foundations&quot;">​</a></h1><p><a href="/Syrolands-Public/guide/combat/overview.html">Player-facing overview</a> · <a href="/Syrolands-Public/game-design/">Specification index</a></p><p><strong>Design status: Accepted foundations and experimental Slice 0 policies; Proposed advanced mechanics. Implementation: Stage 2A natural localized melee plus qualitative Anatomy. Verification: automated tests and first client observation recorded; extended gameplay/balance validation incomplete. Current availability is not verified here.</strong></p><p>Ordinary War Mode/Combatant attacks remain automatic. Advanced interaction is optional input into server-resolved opportunities; it must not require clicking every swing. Eligible participants can undergo local simulation even when they never open an assessment panel.</p><p>Separate a request to hit a region from hit/miss and from the actual impact location. Player decisions and character skills coexist. Client-visible opportunities do not transfer authority to rendering, sprite pixels or animation completion.</p><p>The initial Lab uses UOR/pre-AOS. PvP and PvM share the intended conceptual system; the human-player-only first fixture is a temporary implementation boundary.</p><p>Current ModernUO has timing, hit checks, global Hits, shield/armor mitigation and legacy coverage rolls. Stage 2A integrates the seven-region primitives, session-local player state and natural local trauma without replacing global HP damage. <strong>Gap:</strong> aimed intent, functional disability/shield behavior and gameplay validation remain deferred.</p><p>Read <a href="/Syrolands-Public/game-design/combat/body-regions.html">regions</a>, <a href="/Syrolands-Public/game-design/combat/damage.html">damage</a>, <a href="/Syrolands-Public/game-design/combat/targeting.html">targeting</a> and <a href="/Syrolands-Public/game-design/combat/disability.html">disability</a>. <a href="/Syrolands-Public/game-design/combat/future-directions.html">Future mechanics</a> are outside Slice 0.</p><h2 id="proposed-progression-and-stat-responsiveness" tabindex="-1">Proposed progression and stat responsiveness <a class="header-anchor" href="#proposed-progression-and-stat-responsiveness" aria-label="Permalink to &quot;Proposed progression and stat responsiveness&quot;">​</a></h2><p><a href="/Syrolands-Public/game-design/characters/stats.html">Stats and combat responsiveness</a> requires a believable low-DEX cadence while keeping animation, recovery, attack opportunities, stamina/fatigue and weapon speed distinct. This is Proposed intent; inherited server timing currently depends on stamina and weapon speed in the pre-AOS path. No attacks, timing formulas or client animation are changed here. <a href="/Syrolands-Public/game-design/characters/progression.html">General progression</a> calls for useful low-skill play and future review of mandatory skill investment, preserving automatic combat and server authority.</p><h2 id="combat-foundation-integration" tabindex="-1">Combat foundation integration <a class="header-anchor" href="#combat-foundation-integration" aria-label="Permalink to &quot;Combat foundation integration&quot;">​</a></h2><p><a href="/Syrolands-Public/game-design/combat/weapons-and-damage.html">Weapons and damage families</a>, <a href="/Syrolands-Public/game-design/combat/armor-and-mitigation.html">armor and mitigation</a> and <a href="/Syrolands-Public/game-design/combat/stamina-and-reactive-combat.html">stamina, recovery and reactive input</a> expand Proposed directions around the existing accepted experiment. <a href="/Syrolands-Public/game-design/combat/status-and-open-questions.html">Combat status and open questions</a> separates design from implementation, dated enablement and verification. Mandatory manual attacks would conflict with the accepted automatic baseline; no replacement is selected.</p><p>Character skill determines capability, knowledge informs options, and player execution determines performance within server-resolved rules. Build diversity should avoid requiring every fighter to maximize weapon skill, Tactics, Anatomy and Healing. An illustrative Hunter may mix Archery, Tracking, Animal Lore, Anatomy, Tailoring, Tactics and Healing/Camping at varied levels; a heavy warrior may emphasize armor and melee control; a mage may emphasize spell knowledge, Concentration and positioning. These are Proposed examples, not locked templates or approved optimal builds.</p>',13)])])}const u=a(o,[["render",r]]);export{g as __pageData,u as default};
